type Lease = { secret: string; holder: string; expires: string };

export function LeaseDialog({ lease }: { lease: Lease }) {
  return (
    <div role="dialog" data-testid="lease-dialog" className="p-card rounded-control bg-surface-raised shadow-overlay flex flex-col gap-medium max-w-md">
      <h2 className="text-heading font-bold text-primary">{lease.secret}</h2>
      <p className="text-body text-muted">Held by {lease.holder}, expires {lease.expires}.</p>
      <div className="flex gap-small">
        <button type="button" data-testid="lease-extend" className="h-control px-control rounded-control text-body font-medium bg-action-secondary hover:bg-action-secondary-hover text-primary border border-strong focus:border-action-primary">Extend by 1h</button>
      </div>
    </div>
  );
}
